fn max_of_list(lst: &Vec<usize>) -> usize {
    // Since the vector is guaranteed to be non-empty, it's safe to initialize
    // the maximum with the first element.
    let mut max_val = lst[0];

    // Iterate over the remaining elements and update max_val if we find a larger one.
    for &val in lst.iter().skip(1) {
        if val > max_val {
            max_val = val;
        }
    }

    max_val
}

fn main() {
    let numbers = vec![3, 7, 2, 9, 5];
    println!("The maximum is {}", max_of_list(&numbers)); // Should print "The maximum is 9"
}